window.sleep = (ms) => new Promise((r) => setTimeout(r, ms));
window.until = async (fn, ms = 15000) => { const t0 = Date.now(); while (Date.now() - t0 < ms) { if (await fn()) return true; await sleep(250) } return false };
window.button = (name) => [...document.querySelectorAll('button')].find((x) => x.textContent.trim() === name);
window.check = (label, ok, got) => (ok ? 'OK ' : 'MISMATCH ') + label + ' got ' + JSON.stringify(got);
window.trigger = () => document.querySelector('button[aria-label^="League: "]');
window.league = () => trigger()?.getAttribute('aria-label')?.replace('League: ', '') ?? null;
window.statusLine = () => document.querySelector('[title="See what is loaded"]')?.textContent.trim() ?? null;
window.h1 = () => document.querySelector('main h1')?.textContent.trim() ?? null;
window.reason = () => document.querySelector('main p')?.textContent ?? '';
window.menuItems = async () => { trigger().focus(); trigger().dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); await until(() => document.querySelectorAll('[role=menuitemradio]').length > 0, 3000); return [...document.querySelectorAll('[role=menuitemradio]')] };
window.switchTo = async (name) => { const item = (await menuItems()).find((x) => x.textContent.startsWith(name)); if (!item) return 'NO ITEM ' + name; item.click(); await until(() => league() === name, 5000); await sleep(3000); return league() };
